/* all channel names */
.p-channel_sidebar__name {
   font-size: 12px !important;
}

/* unread channel names */
.p-channel_sidebar__channel--unread:not(.p-channel_sidebar__channel--muted):not(.p-channel_sidebar__channel--suggested) .p-channel_sidebar__name {
   font-weight: 500 !important;
}

.p-channel_sidebar__section_heading {
    font-size: 12px !important;
}

/* channel banner */
.p-channel_sidebar__banner {
   padding: 0px !important;
   background: #77cef3db !important;
   font-size: 10px !important;
   font-weight: normal !important;
}

.p-channel_sidebar__banner--unreads {
    height: 14px !important;
}

.c-icon.p-channel_sidebar__banner_icon {
    display: none !important;
}

/* channel sidebar */
.c-link.p-channel_sidebar__channel {
    padding: 0px !important;
}

.p-workspace__channel_sidebar .c-virtual_list__scroll_container, .p-workspace__channel_sidebar .c-scrollbar__child, .p-workspace__channel_sidebar .c-virtual_list--scrollbar, .p-channel_sidebar__list, .p-channel_sidebar .p-workspace__channel_sidebar {
    width: 200px !important;
}

.p-ia__channel_details__actions {
    padding: 0px !important;
    border: 0px !important;
    background-color: #f7f7f7 !important;
    border-radius: 10px !important;
}

.p-ia__channel_details__action_icon {
    display: none !important;
}

/* current channel */
.channel_name {
   color: #707070 !important;
   font-weight: 500 !important;
   font-size: 16px !important;
}

/* new details sidebar */
.p-classic_nav__right_header--context_pane {
    width: 200px !important;
}

.p-flexpane_header {
    padding: 0px !important;
}

.p-flexpane__title_container {
    font-size: 12px !important;
}

.p-channel_details_section__header {
    padding: 0px !important;
}

.p-channel_details_section__title-content {
    font-size: 12px !important;
}

.p-channel_details_section__icon {
    display: none !important;
}

/* details sidebar */
.p-channel_details__header__faces {
    display: none !important;   
}

#client-ui.flex_pane_showing.details_showing #col_flex {
   flex-basis: 200px !important;
}

.heading {
   color: #707070 !important;
   padding: 0px !important;
   font-size: 12px !important;
}

.heading_text {
   color: #707070 !important;
   font-size: 12px !important;
   font-weight: normal !important;
}

#details_tab_header {
   font-size: 0px !important;
}

.channel_name {
   color: #707070 !important;
   font-size: 12px !important;
   font-weight: normal !important;
}

#details_tab .heading #details_tab_header .ts_icon_lock {
   margin-right: 0px !important;
}

.channel_page_section, .section_header {
   padding: 0px !important;
   font-size: 14px !important;
   min-height: 0px !important;
   overflow: hidden !important;
}

.section_title {
   margin-left: 8px !important;
   font-size: 10px !important;
   font-weight: 500 !important;
}

.ts_icon {
   display: none !important;
}

/* detail sidebar members */
.c-unified_member__display-name, .c-member__presence {
   font-weight: normal !important;
   font-size: 12px !important;
}

.c-member_name, .c-member_name strong {
   font-weight: normal !important;
   font-size: 12px !important;
}

.add_someone {
   font-size: 12px !important;
   margin-left: 8px !important;
}

[data-qa=members-list-invite-button], .p-channel_details__members_list_buttons button {
    font-weight: normal !important;
    font-size: 12px !important;
    height: auto !important;
    color: rgba(119, 206, 243, 0.86) !important;
    border: 0px !important;
}

.p-channel_details__members_list_buttons, [data-qa=members-list-invite-button] {
    padding: 0px !important;
    line-height: 1.0 !important;
    font-size: 12px !important;
    font-weight: normal !important;
    margin-left: 8px !important;
}

/* message list */
.c-message_kit__gutter {
    padding: 8px 0px !important;
}

/* message input */
.p-message_pane_input {
    padding: 0px !important;
    border: 0px !important;
}

.p-notification_bar {
    height: 12px !important;
}

.p-notification_bar__section {
    font-size: 10px !important;
}
}
